O = {
"c447:xo53_2_18": ("**공 주고받기** 균형훈련", "움직이면서 균형을 잡는 공 주고받기·팔 뻗기는 **동적** 균형훈련이에요.", "공 주고받기는 **동적** 균형훈련이다.", "움직이며 버티면 동적", 3),
"c447:xo53_2_39": ("**브란트-다로프** 기법", "브란트-다로프 기법은 어지럼을 반복 유발해 적응시키는 **습관화 운동**이에요. 이석 정복법은 에플레이예요.", "브란트-다로프 기법은 **습관화 운동**이다.", "에플레이 정복, 브란트-다로프 습관화", 3),
"c447:xo53_2_45": ("**소뇌 실조** 보행 훈련", "소뇌 실조 보행은 **느리고 정확하게**, 시각 정보를 활용해 훈련해요.", "소뇌 실조에는 **느리고 정확한** 걸음 훈련이 좋다.", "실조 = 천천히 정확하게", 4),
"c447:xo52_2_46": ("**눈 감고 패드 위 서기**", "시각을 빼고 바닥 감각을 바꾸는 것은 **감각 조작** 훈련이에요. 예측적 균형은 스스로 움직이기 전에 미리 자세를 준비하는 것으로, 팔 뻗기로 훈련해요.", "눈 감고 패드 위 서기는 **감각 조작** 균형 훈련이다.", "눈 감기·폼 = 감각, 팔 뻗기 = 예측", 3),
"c447:xo50_2_35": ("**가면얼굴**", "표정이 굳은 가면얼굴과 작은글씨증은 **파킨슨병**의 특징이에요.", "가면얼굴은 **파킨슨병**의 특징이다.", "가면얼굴 = 파킨슨", 4),
"c448:xo53_2_49": ("**ALS 말기** 목표", "ALS 말기에는 근력 향상보다 **체위변경으로 욕창·구축 예방**과 편안함 유지가 목표예요.", "ALS 말기에는 **체위변경**으로 욕창을 예방한다.", "말기 = 편안하게 지키기", 4),
"c448:xt53_2_49": ("ALS 말기 **물리치료**", "근력운동이 아니라 **욕창 예방 체위변경**이 중심이에요.", "'저항성 근력운동'으로 바꾸면 틀려요.", "말기 = 체위변경", 4),
"c449:xo53_2_37": ("**먼쪽부터 올라가는** 마비", "다리 먼쪽에서 몸쪽으로 대칭적으로 올라가는 마비는 **길랭-바레증후군**이에요.", "먼쪽부터 대칭적으로 올라가는 마비는 **길랭-바레증후군**이다.", "아래서 위로 올라오는 마비 = GBS", 4),
"c449:xo52_1_82": ("**황새다리** 변형", "종아리 근육이 위축돼 황새다리처럼 보이는 것은 **샤르코-마리-투스병**이에요. 길랭-바레는 급성 염증성 탈수초 질환이에요.", "황새다리 변형은 **샤르코-마리-투스병**의 특징이다.", "황새다리 = CMT", 4),
"c449:xo52_2_39": ("다발경화증과 **열**", "다발경화증은 열에 증상이 **악화**돼요(우토프 현상). 뜨거운 목욕은 피해요.", "다발경화증 환자는 뜨거운 목욕을 **피한다**.", "MS는 더위에 약하다", 4),
"c449:xo51_2_38": ("**다발경화증**의 부위", "다발경화증은 **중추신경(뇌·척수)** 의 만성 염증성 말이집탈락 질환이에요.", "다발경화증은 **중추신경** 말이집탈락 질환이다.", "MS = 중추, GBS = 말초", 4),
"c449:xo50_2_38": ("길랭-바레와 **힘줄반사**", "길랭-바레는 말초 탈수초 질환이라 깊은힘줄반사가 **감소·소실**돼요.", "길랭-바레증후군에서는 깊은힘줄반사가 **감소·소실**된다.", "말초 = 반사 사라짐", 4),
"c450:xo53_2_47": ("**샤르코-마리-투스병** 운동", "샤르코-마리-투스병은 유전성 말초신경병으로, **다리 먼쪽 근력 유지** 운동을 해요. 근긴장을 낮추는 운동은 경직 질환용이에요.", "샤르코-마리-투스병에는 **다리 먼쪽 근력 유지** 운동을 한다.", "CMT = 먼쪽이 약해진다", 3),
"c450:xo53_2_48": ("**소아마비후증후군** 운동", "남은 운동신경세포가 오래 과로한 것이 원인이라 **과사용을 피하고 에너지를 보존**해요.", "소아마비후증후군에는 **과사용을 피하고** 에너지를 보존한다.", "지친 신경 = 아껴 쓰기", 3),
"c450:xo52_2_37": ("**근이영양증**의 원인", "진행성 근이영양증은 **근육 자체**의 질환이에요. 척수 운동신경세포 손상은 ALS·척수성 근위축증이에요.", "진행성 근이영양증은 **근육 자체**의 질환이다.", "이영양증 = 근육", 4),
"c450:xo51_2_29": ("**뒤시엔느형** 운동", "과도한 운동은 근육 손상을 키우므로 **피로를 피하고** 부목·보조도구로 구축을 예방해요.", "뒤시엔느형에는 근피로를 **피하는** 운동을 한다.", "근이영양증 = 지치지 않게", 4),
"c450:xo51_2_39": ("**톱니바퀴형 경축**", "톱니바퀴형 경축은 **파킨슨병**의 특징이에요. 프리드라이히 실조는 척수·소뇌 변성으로 실조가 특징이에요.", "톱니바퀴형 경축은 **파킨슨병**의 특징이다.", "톱니바퀴 = 파킨슨", 4),
"c450:xo51_2_48": ("진행성 근위축증 **저항 강도**", "진행성 근위축증은 **과도한 저항을 피해요**. 누워 지내는 단계에서는 호흡근 강화를 해요.", "진행성 근위축증에는 **과도한 저항을 피한다**.", "약해지는 근육은 무리시키지 않는다", 3),
"c450:xo50_2_37": ("**ALS**와 감각", "ALS는 **운동신경세포**만 손상되고 감각은 보존돼요.", "ALS는 **운동신경세포**가 손상되고 감각은 보존된다.", "ALS = 운동만", 5),
"c451:xo51_2_45": ("**치매 환자** 지시 방법", "치매 환자에게는 **한 번에 한 단계씩** 짧고 단순하게 지시하고, 일관된 환경을 유지해요.", "치매 환자에게는 **한 번에 한 단계씩** 설명한다.", "하나씩, 늘 같게", 3),
"c451:xt51_2_45": ("치매 환자 **운동치료 원칙**", "같은 시간·장소에서 **일관된 지시·환경**을 유지해요.", "'매번 다른 환경'으로 바꾸면 틀려요.", "늘 같게", 3),
"c452:xo53_2_40": ("**GCS 5점** 환자", "GCS 5점은 혼수 수준이라 **구축 예방 관절운동과 자세 관리**가 우선이에요.", "GCS 5점 환자는 **구축 예방 관절운동과 자세 관리**를 우선한다.", "혼수 = 몸 지키기", 3),
"c452:xo52_2_32": ("**뇌부종**의 분류", "뇌부종·저산소증은 **이차** 손상이에요. 일차 손상은 충격 순간의 머리뼈 손상·타박 등이에요.", "뇌부종은 **이차적** 손상이다.", "충격 순간 = 1차, 나중에 생기는 것 = 2차", 4),
"c452:xo51_2_31": ("**대뇌 저산소증**의 분류", "저산소증과 부종은 **이차적** 뇌손상이에요.", "대뇌 저산소증은 **이차적** 뇌손상이다.", "저산소·부종 = 2차", 4),
"c452:xo50_2_32": ("1차 손상 후 **2차 손상**", "외상성 뇌손상은 충격 뒤 부종·출혈·저산소증으로 **2차 손상**이 생길 수 있어요. 맞는 문장이에요.", "'2차 손상은 생기지 않는다'고 하면 틀려요.", "2차 = 부종·출혈·저산소", 4),
"c452:xo50_2_42": ("**란초 VII 이상** 치료", "감각자극으로 각성을 높이는 것은 **낮은 수준** 환자예요. VII 이상은 **사회·지역사회 복귀** 훈련을 해요.", "란초 VII 이상 환자에게는 **사회·지역사회 복귀** 훈련을 한다.", "낮으면 깨우고, 높으면 내보낸다", 3),
"c453:xo53_2_41": ("이완 없이 **동심·편심** 반복", "이완 없이 동심·편심·유지 수축을 반복하는 것은 **등장성 수축 혼합**이에요. 율동적 개시는 수동 → 능동보조 → 능동 → 저항으로 진행해요.", "동심·편심 수축을 이완 없이 반복하는 기법은 **등장성 수축 혼합**이다.", "개시 = 수동부터, 혼합 = 쉬지 않고", 4),
"c453:xo52_2_41": ("**PNF**의 원리", "PNF는 적절한 저항으로 **방산**을 일으켜 약한 근육을 강화해요. 원시반사로 공동운동을 촉진하는 것은 브룬스트롬이에요.", "PNF는 **적절한 저항과 방산**으로 약한 근육을 강화한다.", "PNF = 저항 + 방산", 4),
"c453:xo51_2_41": ("**동적 반전**", "동적 반전은 **등장성** 수축을 번갈아 해요. 등척성 수축을 번갈아 하는 것은 율동적 안정화예요.", "**율동적 안정화**는 등척성 수축을 번갈아 유도한다.", "동적 = 움직임, 안정화 = 버팀", 4),
"c453:xo50_2_44": ("**유지-이완**", "유지-이완은 **범위 증가** 기법이에요. 운동 시작을 촉진하는 것은 율동적 개시예요.", "유지-이완은 **관절운동범위 증가** 기법이다.", "이완 = 범위, 개시 = 시작", 4),
"c454:xo50_2_45": ("**루드 접근법** 단계", "루드는 운동성 → 안정성 → 조절된 운동성 → **숙련(기술)** 순이에요. 맞는 문장이에요.", "'마지막 단계는 안정성'이라고 하면 틀려요.", "움직 → 버팀 → 버티며 움직 → 숙련", 4),
"c455:xo50_2_41": ("보바스 **핵심부위**", "보바스의 몸쪽 핵심부위는 **어깨·골반**이고, 손·발은 먼쪽이에요.", "보바스 핵심부위 조절에서 **어깨·골반**이 몸쪽 핵심부위다.", "핵심 = 어깨·골반", 4),
"c455:xt50_2_41": ("어깨·골반 조절로 **안정성**", "어깨·골반을 조절해 팔다리에 안정성을 주는 것은 보바스의 **몸쪽 핵심부위 조절**이에요.", "'먼쪽 핵심부위'로 바꾸면 틀려요.", "핵심 = 어깨·골반", 4),
"c456:xo53_2_43": ("**보이타** 접근법", "보이타는 7가지 자세반응으로 평가하고 **특정 자극점**을 눌러 반사이동을 유도해요. 핵심부위 조절은 보바스예요.", "보이타 접근법은 **자극점을 눌러 반사이동**을 유도한다.", "보이타 = 자극점, 보바스 = 핵심부위", 4),
"c456:xt53_2_43": ("7가지 자세반응 + **자극점**", "7가지 자세반응으로 평가하고 특정 부위를 자극하는 것은 **보이타(반사적 움직임 유도)** 예요.", "'보바스'로 바꾸면 틀려요.", "보이타 = 반사이동", 4),
"c458:xo51_2_42": ("지압과 수동뻗침 = **와츠**", "따뜻한 물에서 치료사가 지압과 수동뻗침으로 이완시키는 것은 **와츠**예요. 할리윅은 스스로 균형을 잡는 10단계 프로그램이에요.", "따뜻한 물에서 지압·수동뻗침으로 이완시키는 방법은 **와츠**다.", "와츠 = 수동, 할리윅 = 스스로", 3),
"c458:xt51_2_42": ("할리윅 **단계 구성**", "할리윅은 **정신적응 → 균형회복 → 억제 → 촉진**으로 진행해요.", "'촉진 → 억제 → 정신적응' 순으로 바꾸면 틀려요.", "적응하고, 균형 잡고, 억제하고, 움직인다", 3),
"c459:xo53_1_20": ("학습에 의한 **재조직**", "경험·학습으로 중추신경 구조와 기능이 재조직되는 것은 **신경가소성**이에요. 음성되먹임은 결과가 원인을 억제하는 조절 방식이에요.", "학습에 의한 신경 재조직은 **신경가소성**이다.", "가소성 = 바뀌는 성질", 4),
"c459:xt53_1_20": ("**경험·학습**으로 재조직", "중추신경이 경험과 학습으로 바뀌는 성질이 **신경가소성**이에요.", "'음성되먹임'으로 바꾸면 틀려요.", "가소성 = 바뀌는 뇌", 4),
"c459:xo53_2_19": ("피츠 **연합 단계**", "피츠는 인지 → 연합 → 자동 순이에요. 동작에 집중하지 않아도 되는 것은 **자동 단계**예요.", "동작에 집중하지 않아도 되는 것은 **자동 단계**다.", "인지 생각, 연합 다듬기, 자동 저절로", 4),
"c459:xt53_2_19": ("**동시 과제** + 환경 적응", "다른 과제를 함께 하며 환경 변화에 쉽게 적응하는 것은 **자동 단계**예요.", "'연합 단계'로 바꾸면 틀려요.", "자동 = 딴생각해도 된다", 4),
"c460:xo53_2_33": ("**무정위형** 근긴장", "무정위형 뇌성마비는 바닥핵 손상으로 근긴장 **변동**이 심하고 불수의 움직임이 나타나요.", "무정위형 뇌성마비는 근긴장이 **변동**한다.", "무정위 = 출렁이는 긴장", 4),
"c460:xo53_2_65": ("**경직** 아동 치료", "경직 아동은 근긴장을 **낮추고** 분리 움직임을 연습시켜요. 두드림은 긴장을 높여요.", "경직 아동은 근긴장을 **낮추는** 치료를 한다.", "높은 긴장은 낮춘다", 4),
"c460:xo52_2_33": ("**바빈스키 양성**", "바빈스키 양성·간대경련 같은 위운동신경세포 징후는 **경직형**이에요. 실조형은 소뇌 손상으로 균형·협응 문제가 나타나요.", "바빈스키 반사 양성은 **경직형** 뇌성마비의 특징이다.", "바빈스키 = 경직형", 4),
"c460:xo51_1_69": ("경직형 양마비 **보행**", "모음근 과긴장으로 다리가 X자로 엇갈리는 **가위보행**이 특징이에요.", "경직형 양마비 아동은 주로 **가위보행**을 한다.", "경직 양마비 = 가위", 5),
"c460:xo51_2_33": ("**경직형** 특징", "경직형은 근긴장이 **높아** 정형화된 운동패턴과 관절구축이 나타나요. 낮은 근긴장은 저긴장형이에요.", "경직형 뇌성마비는 **높은** 근긴장이 특징이다.", "경직 = 높다", 4),
"c460:xo50_2_33": ("**불수의 움직임**", "불수의 움직임이 두드러지는 것은 **무정위형**이에요. 실조형은 균형·협응 문제예요.", "불수의 움직임이 가장 두드러지는 것은 **무정위형**이다.", "무정위 불수의, 실조 균형", 4),
"c461:xo52_1_105": ("**GMFCS**", "대동작기능분류체계(GMFCS)는 **뇌성마비** 아동의 대동작 기능을 5단계로 분류해요. 영아 발달 지연 선별은 AIMS 등이에요.", "대동작기능분류체계는 **뇌성마비** 기능 분류 도구다.", "GMFCS = 뇌성마비 등급", 4),
"c461:xt52_1_105": ("8개월 아기 **운동발달 지연**", "0~18개월 영아의 운동발달은 **앨버타 유아운동발달평가(AIMS)** 로 평가해요.", "'GMFCS'로 바꾸면 틀려요.", "아기 = AIMS", 4),
}
